"""Generate docs/TESTING.md from eval/results/results.json (the only source of numbers)."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
R = json.loads((ROOT / "eval" / "results" / "results.json").read_text(encoding="utf-8"))
S = R["summary"]


def pct(a, b):
    return f"{a}/{b} ({100 * a / b:.0f}%)" if b else "n/a"


def main():
    t = S["solver_on_truth"]
    L = [
        "# Testing",
        "",
        "_Generated by `eval/make_testing.py` from `eval/results/results.json`. Do not edit numbers by hand._",
        "",
        f"- Run at: {S['run_at']}  ·  model: `{S['model'] or 'not used (no API key in this run)'}`",
        f"- Data: **fully synthetic**. {S['n_cases']} cases generated by `eval/gen_cases.py` "
        f"({S['n_feasible']} feasible, {S['n_infeasible']} genuinely infeasible), team sizes {S['team_size_range'][0]}–{S['team_size_range'][1]}, "
        "2-week horizon, 3 shifts/day, default coverage of 2 people per shift. Ground-truth constraints were written first, "
        "then rendered into Azerbaijani / Russian / mixed / no-diacritics text by templates"
        + (f"; {S['paraphrased_cases']} cases were then paraphrased informally by the LLM (kept only when every number survived)." if S["paraphrased_cases"] else
           " (no LLM paraphrasing in this run, so the text is more regular than real manager messages)."),
        "- Unit tests: `pytest` — each of the 8 rule types has a passing and a failing verifier test; solver, repair, parser name resolution are covered.",
        "",
        "## 0. Solver on ground-truth constraints (no LLM)",
        "",
        "| check | result |", "|---|---|",
        f"| feasible cases solved | {pct(t['feasible_cases_solved'], S['n_feasible'])} |",
        f"| …with 0 violations by the independent verifier | {pct(t['feasible_cases_zero_violations'], S['n_feasible'])} |",
        f"| infeasible cases detected | {pct(t['infeasible_detected'], S['n_infeasible'])} |",
        f"| reported conflict core exactly equals the planted rules | {pct(t['core_exact'], S['n_infeasible'])} |",
        f"| median / max solve time | {t['median_solve_seconds']} s / {t['max_solve_seconds']} s (20 s limit) |",
        "",
    ]
    if S.get("understanding"):
        u, sc, inf = S["understanding"], S["schedules"], S["infeasible"]
        L += [
            "## 1. Rule understanding (LLM parser)",
            "",
            "A constraint sentence counts as correct only if every field matches the ground truth exactly (type, person, days, shift, numbers).",
            "",
            "| style | correct |", "|---|---|",
            *[f"| {k} | {pct(v['correct'], v['total'])} |" for k, v in u["by_style"].items()],
            f"| **all** | **{pct(u['constraint_sentences_correct'], u['constraint_sentences'])}** |",
            "",
            f"- Sentences that should be flagged (ambiguous or unsupported): {u['should_flag']}; flagged correctly: {u['flagged_correctly']}; "
            f"**wrongly accepted as rules: {u['wrongly_accepted']}**.",
            f"- Valid rules wrongly flagged as ambiguous/unsupported: {u['valid_rules_wrongly_flagged']}. Parse errors (validation failed twice): {u['parse_errors']}.",
            f"- Median parse time per case: {u['median_parse_seconds']} s.",
            "",
            "## 2. Schedule correctness: Növbə vs chatbot baseline",
            "",
            "Both are scored by the same independent verifier (`novbe/verifier.py`) against the **ground-truth** rules. "
            "Baseline = the same rules in a careful plain prompt (`eval/baseline_chatbot.py`), same model.",
            "",
            "| | Növbə (parse → confirm-as-is → solve) | chatbot baseline |", "|---|---|---|",
            f"| schedules produced | {sc['novbe_e2e_schedules']}/{S['n_feasible']} | {sc['baseline_schedules']}/{S['n_feasible']} (invalid output: {sc['baseline_invalid_output']}) |",
            f"| schedules with 0 violations | {sc['novbe_e2e_zero_violations_vs_truth']} | {sc['baseline_zero_violations']} |",
            f"| total violations | {sc['novbe_e2e_total_violations_vs_truth']} | {sc['baseline_total_violations']} |",
            f"| median time | solve {sc['novbe_median_e2e_solve_seconds']} s (+ parse) | {sc['baseline_median_seconds']} s |",
            "",
            f"Against the rules it actually parsed, Növbə's schedules had 0 violations in {sc['novbe_e2e_zero_violations_vs_parsed']}/{sc['novbe_e2e_schedules']} cases; "
            "any violation against ground truth comes from a parsing mistake, which is exactly what the confirmation step is for "
            "(the eval confirms everything as-is, i.e. it assumes the manager does not catch any mistake).",
            "",
            "## 3. Infeasible rule sets",
            "",
            f"- End to end (parse → solve): infeasibility detected in {pct(inf['e2e_detected'], S['n_infeasible'])}; "
            f"reported conflicting sentences exactly equal the planted ones in {pct(inf['e2e_core_exact'], S['n_infeasible'])}.",
            "",
        ]
    else:
        L += ["## 1–3. LLM parts", "", "Not run: no `ANTHROPIC_API_KEY` was available for this run.", ""]
    L += [
        "## Real failures",
        "",
        "See `eval/results/failures.md` (auto-collected from this run).",
        "",
        "## Human baseline",
        "",
        "- Time for a person to build one 4-week rota for 12 staff by hand with the demo rules: **[to be filled in by the team — measured manually]**",
        "",
        "## Reproduce",
        "",
        "```bash",
        "python -m eval.gen_cases",
        "python -m eval.run_eval",
        "python -m eval.make_testing",
        "```",
    ]
    (ROOT / "docs" / "TESTING.md").write_text("\n".join(L) + "\n", encoding="utf-8")
    print("wrote docs/TESTING.md")


if __name__ == "__main__":
    main()
